node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Verify only one row will be affected
const before = db.prepare(\"SELECT booking_id, cabin_class, price_paid FROM flight_bookings WHERE booking_id = 'BK-B70889'\").get();
console.log('BEFORE:', JSON.stringify(before));

// Count total bookings (to verify no others are touched)
const totalBefore = db.prepare('SELECT COUNT(*) as cnt FROM flight_bookings').get();
console.log('Total bookings:', totalBefore.cnt);

// Execute the update
const result = db.prepare(\"UPDATE flight_bookings SET cabin_class = 'premium_economy', price_paid = 780 WHERE booking_id = 'BK-B70889'\").run();
console.log('Rows changed:', result.changes);

// Verify after
const after = db.prepare(\"SELECT booking_id, cabin_class, price_paid FROM flight_bookings WHERE booking_id = 'BK-B70889'\").get();
console.log('AFTER:', JSON.stringify(after));

// Confirm no other bookings were modified
const totalAfter = db.prepare('SELECT COUNT(*) as cnt FROM flight_bookings').get();
console.log('Total bookings after:', totalAfter.cnt);

// Double-check no other booking has unexpected changes
const others = db.prepare(\"SELECT booking_id, cabin_class, price_paid FROM flight_bookings WHERE booking_id != 'BK-B70889'\").all();
console.log('Other bookings (unchanged):');
others.forEach(b => console.log(' ', JSON.stringify(b)));
"

